public boolean validate()
{
    boolean ret;

    ret = next validate()
        && this.RRBIsFantasyBook();

    return ret;
}

private boolean RRBIsFantasyBook()
{
    SalesTable salesTable = this.dataSource().cursor();

    if(RRBBookTable::findRecId(salesTable.RRBBookTable).Genre != RRBGenreEnum::Fantasy)
    {
        return checkFailed("@ITFormacion:YouMustSelectFantasyBooks");
    }

    return true;
}
